<?php

/**
 * Shared subject store for the admin portal.
 *
 * Used by subjects.php (add / edit / view) and schedule.php (subject dropdown),
 * so a subject added on one page is available on the other.
 *
 * A subject has: id, code, title, description.
 * The code is a random 5-digit number generated by the server (for Moodle),
 * and it never changes once created.
 *
 * DUMMY DATA: subjects live in $_SESSION["subjects"] so adding and editing
 * works while you test. Replace subjects_all() / subjects_save() with database
 * queries later; the rest of the code only goes through these helpers.
 */

const SUBJECT_CODE_DIGITS = 5;

function subjects_session(): void
{
    if (session_status() !== PHP_SESSION_ACTIVE) {
        session_start();
    }
}

function subjects_default(): array
{
    // ids 1-6 match the subjects the schedule page already used
    return [
        ["id" => 1, "code" => "48213", "title" => "Web Systems and Technologies",         "description" => "Building and deploying dynamic web applications."],
        ["id" => 2, "code" => "60587", "title" => "Information Assurance and Security",   "description" => "Principles and practice of securing information systems."],
        ["id" => 3, "code" => "73104", "title" => "Systems Integration and Architecture", "description" => ""],
        ["id" => 4, "code" => "29940", "title" => "Capstone Project 1",                   "description" => "Proposal and initial development of the capstone project."],
        ["id" => 5, "code" => "81356", "title" => "Ethics",                               "description" => ""],
        ["id" => 6, "code" => "35072", "title" => "Physical Education 4",                 "description" => "Team sports and fitness."],
        ["id" => 7, "code" => "54701", "title" => "Data Structures and Algorithms",       "description" => ""],
        ["id" => 8, "code" => "92468", "title" => "Database Management Systems",          "description" => ""],
        ["id" => 9, "code" => "16839", "title" => "Discrete Mathematics",                 "description" => ""],
    ];
}

/** Every subject as a list of rows, sorted by code. */
function subjects_all(): array
{
    subjects_session();
    if (!isset($_SESSION["subjects"]) || !is_array($_SESSION["subjects"])) {
        $_SESSION["subjects"] = subjects_default();
    }
    $rows = [];
    foreach ($_SESSION["subjects"] as $row) {
        // Old saved rows may still carry units/department: keep only what we use now
        $rows[] = [
            "id" => (int) $row["id"],
            "code" => (string) $row["code"],
            "title" => (string) $row["title"],
            "description" => (string) ($row["description"] ?? ""),
        ];
    }
    usort($rows, fn($a, $b) => strnatcasecmp($a["code"], $b["code"]));
    return $rows;
}

/** Persist the full list. */
function subjects_save(array $rows): void
{
    subjects_session();
    $_SESSION["subjects"] = array_values($rows); // TODO: INSERT / UPDATE subjects ...
}

/** The shape schedule.php expects: [id => ["code" => ..., "title" => ...]]. */
function subjects_for_schedule(): array
{
    $out = [];
    foreach (subjects_all() as $row) {
        $out[$row["id"]] = ["code" => $row["code"], "title" => $row["title"]];
    }
    return $out;
}

/** A random 5-digit code (10000-99999) that no existing subject uses. */
function subject_generate_code(array $existing): string
{
    $taken = array_column($existing, "code");
    for ($try = 0; $try < 200; $try++) {
        $code = (string) random_int(10 ** (SUBJECT_CODE_DIGITS - 1), 10 ** SUBJECT_CODE_DIGITS - 1);
        if (!in_array($code, $taken, true)) {
            return $code;
        }
    }
    throw new RuntimeException("Could not find a free subject code.");
}

/**
 * Validate posted subject data (title and description only; the code is generated).
 * Returns [$errors, $clean]; $clean is only meaningful when $errors is empty.
 */
function subject_validate(array $input): array
{
    $errors = [];
    $clean = [
        "title" => preg_replace('/\s+/', " ", trim((string) ($input["title"] ?? ""))),
        "description" => trim((string) ($input["description"] ?? "")),
    ];

    if ($clean["title"] === "") {
        $errors[] = "Enter a subject title.";
    } elseif (mb_strlen($clean["title"]) > 120) {
        $errors[] = "The subject title must be 120 characters or fewer.";
    }

    if (mb_strlen($clean["description"]) > 300) {
        $errors[] = "The description must be 300 characters or fewer.";
    }

    return [$errors, $clean];
}
